#!/bin/bash
#
# GitHub Actions runners: RUNNER_COUNT copies of the runner in
# ~RUNNER_USER/RUNNERS_DIR/runner-N, registered as RUNNER_NAME_PREFIX-N, each
# with its proxy .env and a LaunchAgent generated by the runner's own svc.sh.
#
# A runner that is not registered on this machine gets its registration back
# from backup.sh's copy (secrets/runners/runner-N) when that matches its name
# and GITHUB_URL; it then reconnects as the same runner, with no token.
#
# stdin: line 1 = a registration token (only needed for runners that are
# neither registered nor in the backup, or all of them with RUNNER_RECONFIGURE=1).

. "$(dirname "$0")/../lib/remote.sh"
token="$(read_secret)"
exec </dev/null

id "$RUNNER_USER" >/dev/null 2>&1 || die "$RUNNER_USER does not exist; run the 'user' step first"

case "$(uname -m)" in
    arm64)  platform=osx-arm64 ;;
    x86_64) platform=osx-x64 ;;
    *) die "unsupported architecture $(uname -m)" ;;
esac

step "Actions runner package"
if [ "$RUNNER_VERSION" = latest ]; then
    release_url=https://api.github.com/repos/actions/runner/releases/latest
else
    release_url="https://api.github.com/repos/actions/runner/releases/tags/v${RUNNER_VERSION#v}"
fi
release="$(curl -fsSL "$release_url")" || die "could not query $release_url"
version="$(printf '%s' "$release" | plutil -extract tag_name raw -o - -)"
version="${version#v}"
body="$(printf '%s' "$release" | plutil -extract body raw -o - -)"
# The release notes carry each package's checksum between these markers.
sha256="$(printf '%s' "$body" | sed -nE "s/.*<!-- BEGIN SHA ${platform} -->([0-9a-f]{64})<!-- END SHA ${platform} -->.*/\1/p" | head -1)"

tarball="actions-runner-${platform}-${version}.tar.gz"
cache="$SETUP_ROOT/cache"
mkdir -p "$cache"
if [ ! -f "$cache/$tarball" ]; then
    say "Downloading runner $version"
    curl -fL --retry 3 -o "$cache/$tarball.part" \
        "https://github.com/actions/runner/releases/download/v${version}/${tarball}"
    mv "$cache/$tarball.part" "$cache/$tarball"
fi
if [ -n "$sha256" ]; then
    echo "$sha256  $cache/$tarball" | shasum -a 256 -c - >/dev/null \
        || { rm -f "$cache/$tarball"; die "checksum mismatch for $tarball"; }
    ok "runner $version ($platform), checksum verified"
else
    warn "no checksum in the release notes for $platform; not verified"
fi
chmod 644 "$cache/$tarball"
chmod 755 "$SETUP_ROOT" "$cache"   # the runner account extracts from here

step "Runners"
as_runner mkdir -p "$RUNNERS_ROOT"
install_file "$SETUP_ROOT/files/runner/cleanup.sh" "$RUNNERS_ROOT/cleanup.sh" "$RUNNER_USER:staff" 755

env_file="$(mktemp)"
trap 'rm -f "$env_file"' EXIT
render "$SETUP_ROOT/files/runner/runner.env" > "$env_file"

# What the runner's PATH is when it runs as a LaunchAgent (runsvc.sh reads .path).
runner_path="$HOMEBREW_PREFIX/bin:$HOMEBREW_PREFIX/sbin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin:/Library/Apple/usr/bin"

extra_args=()
[ -z "$RUNNER_LABELS" ] || extra_args+=(--labels "$RUNNER_LABELS")
[ -z "$RUNNER_GROUP" ]  || extra_args+=(--runnergroup "$RUNNER_GROUP")

i=1
while [ "$i" -le "$RUNNER_COUNT" ]; do
    name="${RUNNER_NAME_PREFIX}-${i}"
    dir="$RUNNERS_ROOT/runner-$i"
    say "$name ($dir)"
    as_runner mkdir -p "$dir"

    backup="$SETUP_ROOT/secrets/runners/runner-$i"
    if sudo test -f "$dir/.runner" && ! is_true "${RUNNER_RECONFIGURE:-0}"; then
        ok "already registered"
    elif ! is_true "${RUNNER_RECONFIGURE:-0}" && runner_backup_matches "$backup" "$name"; then
        if ! sudo test -x "$dir/config.sh"; then
            as_runner tar -xzf "$cache/$tarball" -C "$dir"
        fi
        for f in .runner .runner_migrated .credentials .credentials_rsaparams; do
            [ ! -f "$backup/$f" ] || install_file "$backup/$f" "$dir/$f" "$RUNNER_USER:staff" 600
        done
        # config.sh normally writes svc.sh from this template; it names the
        # service actions.runner.<org or owner-repo>.<runner name>.
        if ! sudo test -f "$dir/svc.sh"; then
            scope="${GITHUB_URL#https://github.com/}"
            scope="${scope%/}"
            scope="${scope//\//-}"
            as_runner_in "$dir" /bin/bash -c 'sed -e "s/{{SvcNameVar}}/$1/" -e "s/{{SvcDescription}}/$2/" bin/darwin.svc.sh.template > svc.sh && chmod 755 svc.sh' \
                _ "actions.runner.$scope.$name" "GitHub Actions Runner ($scope.$name)"
        fi
        ok "restored the registration of $name (agent $(runner_json "$backup/.runner" agentId)) from the backup"
    else
        [ -n "$token" ] || die "a registration token is needed to register $name"
        if sudo test -f "$dir/.service"; then
            plist="$(sudo cat "$dir/.service")"
            [ -z "$RUNNER_UID" ] || sudo launchctl bootout "gui/$RUNNER_UID" "$plist" 2>/dev/null || true
            as_runner_in "$dir" ./svc.sh uninstall >/dev/null 2>&1 || true
        fi
        if sudo test -f "$dir/.runner"; then
            as_runner_in "$dir" ./config.sh remove --token "$token" || true
        fi
        if ! sudo test -x "$dir/config.sh"; then
            as_runner tar -xzf "$cache/$tarball" -C "$dir"
        fi
        # --replace takes over the registration of a runner with the same name,
        # which is what a re-imaged machine leaves behind on GitHub.
        as_runner_in "$dir" ./config.sh --unattended --replace \
            --url "$GITHUB_URL" --token "$token" --name "$name" \
            --work "$RUNNER_WORK_DIR" ${extra_args[@]+"${extra_args[@]}"}
        ok "registered $name"
    fi

    install_file "$env_file" "$dir/.env" "$RUNNER_USER:staff" 644
    [ "$INSTALL_CHANGED" = 0 ] || warn "$name: .env changed; the runner picks it up when restarted"
    printf '%s\n' "$runner_path" > "$env_file.path"
    install_file "$env_file.path" "$dir/.path" "$RUNNER_USER:staff" 644
    rm -f "$env_file.path"

    if ! sudo test -f "$dir/.service"; then
        as_runner_in "$dir" ./svc.sh install >/dev/null
        ok "LaunchAgent $(basename "$(sudo cat "$dir/.service")")"
    else
        ok "LaunchAgent $(basename "$(sudo cat "$dir/.service")") already installed"
    fi
    i=$((i + 1))
done

# Directories beyond RUNNER_COUNT are left from an earlier, larger setup.
for dir in "$RUNNERS_ROOT"/runner-*; do
    [ -d "$dir" ] || continue
    n="${dir##*-}"
    case "$n" in *[!0-9]*) continue ;; esac
    if [ "$n" -gt "$RUNNER_COUNT" ]; then
        warn "$dir is beyond RUNNER_COUNT=$RUNNER_COUNT. To retire it: cd $dir && ./svc.sh uninstall && ./config.sh remove --token <token>"
    fi
done
